-- Synthetic isolated test database export ONLY. No actual source workbooks.
SELECT jsonb_build_object(
 'centres',(SELECT jsonb_agg(jsonb_build_object('id',c.id,'name',c.label,'donor',d.label,'officers',(SELECT coalesce(jsonb_agg(DISTINCT a.staff_member_id),'[]'::jsonb) FROM mass_core.centre_staff_assignments a WHERE a.centre_id=c.id AND role_code='Cluster Officer'))) FROM mass_core.centres c LEFT JOIN mass_core.donors d ON d.id=c.donor_id),
 'db',jsonb_build_object('academicYear','20000000-0000-4000-8000-000000000001','students',(SELECT jsonb_agg(jsonb_build_object('id',e.id,'enrolmentId',e.id,'childId',e.child_id,'studentId',c.student_id,'centre',e.centre_id,'grade',e.grade_label,'shift',e.shift_code,'gender',p.gender_code,'enrolled',e.starts_on,'exitDate',e.ends_before)) FROM mass_core.enrolments e JOIN mass_core.children c ON c.id=e.child_id LEFT JOIN mass_core.private_child_profiles p ON p.child_id=e.child_id),
 'attendanceRecords',(SELECT coalesce(jsonb_object_agg(id::text,to_jsonb(a)),'{}'::jsonb) FROM mass_core.attendance_records a),
 'attendance',(SELECT coalesce(jsonb_object_agg(enrolment_id::text||'|'||attendance_date::text,code),'{}'::jsonb) FROM mass_core.attendance_records),
 'calendar',(SELECT coalesce(jsonb_agg(jsonb_build_object('centre',centre_id,'date',session_date,'shift',shift_code,'status',CASE WHEN is_scheduled THEN 'Planned' ELSE 'Not Scheduled' END)),'[]'::jsonb) FROM mass_core.cac_sessions),
 'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'centre',centre_id,'date',activity_date,'shift',shift_code,'name',name,'category',category,'status',delivery_status)),'[]'::jsonb) FROM mass_core.activity_events),
 'participationRecords',(SELECT coalesce(jsonb_object_agg(id::text,to_jsonb(a)),'{}'::jsonb) FROM mass_core.activity_participation a),
 'sessions',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'centre',centre_id,'date',session_date,'shift',shift_code,'status',status)),'[]'::jsonb) FROM mass_core.cac_delivery_records),
 'assessmentDetails',(SELECT coalesce(jsonb_object_agg(a.enrolment_id::text||'|F'||q.quarter,jsonb_build_object('id',a.id,'enrolment_id',a.enrolment_id,'score',a.score,'maxMarks',d.max_score,'date',a.assessed_on,'definition_id',d.id,'academicYear',q.academic_year_id)),'{}'::jsonb) FROM mass_core.assessment_results a JOIN mass_core.assessment_definitions d ON d.id=a.definition_id JOIN mass_core.assessment_periods q ON q.id=d.period_id),
 'references',jsonb_build_object('academic_years',(SELECT jsonb_agg(to_jsonb(y)) FROM mass_core.academic_years y),'assessment_periods',(SELECT jsonb_agg(to_jsonb(q)) FROM mass_core.assessment_periods q),'assessment_definitions',(SELECT jsonb_agg(to_jsonb(d)) FROM mass_core.assessment_definitions d)),
 'morarjiHistory',(SELECT coalesce(jsonb_agg(jsonb_build_object('s',jsonb_build_object('id',e.id,'childId',e.child_id,'centre',e.centre_id,'grade',e.grade_label,'shift',e.shift_code,'gender',p.gender_code,'enrolled',e.starts_on,'exitDate',e.ends_before),'cohort_id',c.id,'cohort',c.label,'cohortAcademicYear',c.academic_year_id,'applied',o.applied,'attended',o.attended,'passed',o.passed)),'[]'::jsonb) FROM mass_core.cohort_memberships m JOIN mass_core.enrolments e ON e.id=m.enrolment_id JOIN mass_core.programme_cohorts c ON c.id=m.cohort_id LEFT JOIN mass_core.private_child_profiles p ON p.child_id=e.child_id LEFT JOIN mass_core.morarji_outcomes o ON o.membership_id=m.id))
);
